<script>
  import { toLower, toSentence, toTitle, toUpper } from '@splendidlabz/utils'
  import { init } from '../../utils'
  import Icon from '../Icon/Icon.svelte'
  import { Snippet } from '../_Shared/Snippet.svelte'

  const {
    class: klass = '',
    aClass = null,
    currentClass = null,
    ariaCurrentType = 'page',
    isLast = null,
    divider = 'tabler:chevron-right',
    dividerClass = '',
    href = '',
    labelCase = 'title',
    label: rawLabel,

    // Slots
    before,

    ...rest
  } = $props()

  const label = $derived.by(() => {
    if (labelCase === 'title') return toTitle(rawLabel)
    if (labelCase === 'sentence') return toSentence(rawLabel)
    if (labelCase === 'upper') return toUpper(rawLabel)
    if (labelCase === 'lower') return toLower(rawLabel)
    return rawLabel
  })

  // Check aria current type
  init(() => {
    if (
      !['page', 'time', 'step', 'location', 'date'].includes(ariaCurrentType)
    ) {
      console.warn(`Invalid aria-current type: ${ariaCurrentType}`)
    }
  })

  const current = $derived(isLast && ariaCurrentType)
</script>

<!-- Before slots are for custom icons -->
<li {...rest} class="crumb {klass}">
  {#if isLast}
    {@render Snippet.block(before)}
    <span class={currentClass} aria-current={current}>{label}</span>
  {:else}
    {@render Snippet.block(before)}
    <a class={aClass} {href}>{label}</a>
    <div class="crumb-divider">
      <Icon class={dividerClass} icon={divider} />
    </div>
  {/if}
</li>
